.inject-content {
    font-size: 0.85rem;
    line-height: 1.4;
}

/* Response Node */
.response-node {
    background: var(--bg-panel);
    border-radius: 8px;
    padding: 1rem;
    border-left: 3px solid var(--success-green);
    opacity: 0;
    transform: translateY(10px);
    transition: all 0.4s ease;
}

.response-node.visible {
    opacity: 1;
    transform: translateY(0);
}

.response-label {
    font-size: 0.75rem;
    color: var(--success-green);
    text-transform: uppercase;
    margin-bottom: 0.5rem;
}

.response-content {
    font-size: 0.9rem;
    color: var(--text-secondary);
}

/* Spawn Arrow */
.spawn-arrow, .return-arrow {
    width: 50px;
    height: 2px;
    background: var(--agent-teal);
    margin: 1rem auto;
    position: relative;
    opacity: 0;
    transition: all 0.4s ease;
}

.spawn-arrow.visible, .return-arrow.visible {
    opacity: 1;
}

.spawn-arrow::after {
    content: '';
    position: absolute;
    right: 0;
    top: -4px;
    width: 0;
    height: 0;
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
    border-left: 8px solid var(--agent-teal);
}

.return-arrow::after {
    content: '';
    position: absolute;
    left: 0;
    top: -4px;
    width: 0;
    height: 0;
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
    border-right: 8px solid var(--agent-teal);
}

/* Agent Work */
.agent-work {
    padding: 0.5rem;
}

.work-item {
    padding: 0.5rem;
    font-size: 0.85rem;
    color: var(--text-secondary);
    opacity: 0;
    transform: translateX(-10px);
    transition: all 0.3s ease;
}

.work-item.visible {
    opacity: 1;
    transform: translateX(0);
}

.work-item::before {
    content: '>';
    margin-right: 0.5rem;
    color: var(--agent-teal);
}

/* Summary Return */
.summary-return {
    background: var(--bg-panel);
    border-radius: 8px;
    padding: 1rem;
    border-left: 3px solid var(--agent-teal);
    opacity: 0;
    transform: translateY(10px);
    transition: all 0.4s ease;
}

.summary-return.visible {
    opacity: 1;
    transform: translateY(0);
}

.summary-label {
    font-size: 0.75rem;
    color: var(--agent-teal);
    text-transform: uppercase;
    margin-bottom: 0.5rem;
}

.summary-content {
    font-size: 0.9rem;
    color: var(--text-secondary);
}

/* Panel Info Badges */
.panel-info {
    display: flex;
    gap: 0.5rem;
    justify-content: center;
    margin-top: 1rem;
    flex-wrap: wrap;
}

.info-badge {
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.info-badge.inline {
    background: rgba(124, 58, 237, 0.2);
    color: var(--claude-purple-light);
}

.info-badge.shared {
    background: rgba(59, 130, 246, 0.2);
    color: var(--context-blue);
}

.info-badge.isolated {
    background: rgba(20, 184, 166, 0.2);
    color: var(--agent-teal);
}

.info-badge.separate {
    background: rgba(249, 115, 22, 0.2);
    color: var(--claude-orange-light);
}

/* Comparison Section */
.comparison-section {
    margin-bottom: 3rem;
}

.comparison-section h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

.cards-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

@media (max-width: 700px) {
    .cards-container {
        grid-template-columns: 1fr;
    }
}

.card-column {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.card-column h4 {
    text-align: center;
    color: var(--claude-purple-light);
    margin-bottom: 0.5rem;
}

/* Flip Cards */
.flip-card {
    height: 80px;
    perspective: 1000px;
    cursor: pointer;
}

.flip-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transition: transform 0.6s;
    transform-style: preserve-3d;
}

.flip-card:hover .flip-card-inner {
    transform: rotateX(180deg);
}

.flip-card-front, .flip-card-back {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: 8px;
    display: flex;
    align-items: center;
    padding: 1rem;
}

.flip-card-front {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    gap: 0.75rem;
}

.flip-card[data-type="strength"] .flip-card-front {
    border-left: 3px solid var(--success-green);
}

.flip-card[data-type="tradeoff"] .flip-card-front {
    border-left: 3px solid var(--tradeoff-amber);
}

.flip-card-back {
    background: var(--bg-panel);
    border: 1px solid var(--border-color);
    transform: rotateX(180deg);
    font-size: 0.9rem;
    color: var(--text-secondary);
    line-height: 1.4;
}

.card-icon {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 1.2rem;
    flex-shrink: 0;
}

.flip-card[data-type="strength"] .card-icon {
    background: rgba(34, 197, 94, 0.2);
    color: var(--success-green);
}

.flip-card[data-type="tradeoff"] .card-icon {
    background: rgba(245, 158, 11, 0.2);
    color: var(--tradeoff-amber);
}

/* Wizard Section */
.wizard-section {
    margin-bottom: 3rem;
}

.wizard-section h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

.wizard-container {
    background: var(--bg-card);
    border-radius: 12px;
    padding: 2rem;
    max-width: 600px;
    margin: 0 auto;
    border: 1px solid var(--border-color);
}

.wizard-question p {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
    text-align: center;
}

.wizard-options {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.wizard-option {
    padding: 1rem 1.5rem;
    border: 2px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-panel);
    color: var(--text-primary);
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s ease;
    text-align: left;
}

.wizard-option:hover {
    border-color: var(--claude-purple);
    background: rgba(124, 58, 237, 0.1);
}

.wizard-result {
    text-align: center;
}

.result-recommendation {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    padding: 1rem;
    border-radius: 8px;
}

.result-recommendation.skills {
    background: linear-gradient(135deg, var(--claude-purple) 0%, #4c1d95 100%);
}

.result-recommendation.subagents {
    background: linear-gradient(135deg, var(--agent-teal) 0%, #0d9488 100%);
}

.result-explanation {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    line-height: 1.6;
}

/* Reference Section */
.reference-section h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

.reference-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

@media (max-width: 700px) {
    .reference-grid {
        grid-template-columns: 1fr;
    }
}

.reference-card {
    background: var(--bg-card);
    border-radius: 12px;
    padding: 1.5rem;
    border: 1px solid var(--border-color);
}

.reference-card h4 {
    color: var(--claude-purple-light);
    margin-bottom: 1rem;
}

.reference-card ul {
    list-style: none;
}

.reference-card li {
    padding: 0.5rem 0;
    padding-left: 1.5rem;
    position: relative;
    color: var(--text-secondary);
}

.reference-card li::before {
    content: '>';
    position: absolute;
    left: 0;
    color: var(--claude-purple);
}

/* Footer */
footer {
    text-align: center;
    padding: 2rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
    border-top: 1px solid var(--border-color);
    margin-top: 2rem;
}

/* Animations */
@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.animating .node-icon {
    animation: pulse 1s ease-in-out infinite;
}

input.content:
// Scenario Data
const scenarios = {
    review: {
        userMessage: '"Run /review on this PR"',
        skillInject: 'Review guidelines: Check for bugs, security issues, code style...',
        skillResponse: 'I found 3 issues: 1) Missing null check on line 42, 2) SQL injection risk...',
        subagentUserMessage: '"Review this PR thoroughly"',
        agentWork: ['Reading PR diff...', 'Analyzing 12 changed files', 'Checking against patterns'],
        summaryContent: 'PR has 3 critical issues and 5 suggestions. See detailed report.'
    },
    explore: {
        userMessage: '"How does auth work here?"',
        skillInject: 'Explore patterns: Look for auth middleware, JWT handling, session management...',
        skillResponse: 'Based on what I can see, auth uses JWT tokens stored in cookies...',
        subagentUserMessage: '"Explore the auth system"',
        agentWork: ['Searching for auth files...', 'Reading 47 related files', 'Mapping dependencies'],
        summaryContent: 'Auth system uses JWT + refresh tokens. Key files: auth.ts, middleware.ts, session.ts'
    },
    standards: {
        userMessage: '"Follow our coding standards"',
        skillInject: 'Team standards: Use TypeScript strict mode, prefer functional components...',
        skillResponse: 'I\'ll follow your standards: TypeScript strict, functional components, etc.',
        subagentUserMessage: '"Check code against standards"',
        agentWork: ['Loading .eslintrc...', 'Scanning 200+ files', 'Comparing patterns'],
        summaryContent: '15 files don\'t match standards. Main issues: missing types, class components.'
    }
};

// Current state
let currentScenario = 'review';
let isPlaying = false;
let animationTimeouts = [];

// DOM Elements
const scenarioButtons = document.querySelectorAll('.scenario-btn');
const playBtn = document.getElementById('playBtn');
const resetBtn = document.getElementById('resetBtn');

// Skills Animation Elements
const skillUser = document.getElementById('skillUser');
const skillUserMsg = document.getElementById('skillUserMsg');
const skillArrow1 = document.getElementById('skillArrow1');
const skillClaude = document.getElementById('skillClaude');
const skillArrow2 = document.getElementById('skillArrow2');
const skillInject = document.getElementById('skillInject');
const skillInjectContent = document.getElementById('skillInjectContent');
const skillArrow3 = document.getElementById('skillArrow3');
const skillResponse = document.getElementById('skillResponse');
const skillResponseContent = document.getElementById('skillResponseContent');

// Subagents Animation Elements
const subagentUser = document.getElementById('subagentUser');
const subagentUserMsg = document.getElementById('subagentUserMsg');
const subagentArrow1 = document.getElementById('subagentArrow1');
const subagentClaude = document.getElementById('subagentClaude');
const spawnArrow = document.getElementById('spawnArrow');
const agentContext = document.getElementById('agentContext');
const work1 = document.getElementById('work1');
const work2 = document.getElementById('work2');
const work3 = document.getElementById('work3');
const returnArrow = document.getElementById('returnArrow');
const summaryReturn = document.getElementById('summaryReturn');
const summaryContent = document.getElementById('summaryContent');

// Wizard Elements
const wizardQuestion = document.getElementById('wizardQuestion');
const wizardOptions = document.getElementById('wizardOptions');
const wizardResult = document.getElementById('wizardResult');
const questionText = document.getElementById('questionText');
const resultRecommendation = document.getElementById('resultRecommendation');
const resultExplanation = document.getElementById('resultExplanation');
const restartWizard = document.getElementById('restartWizard');

// Wizard Questions
const wizardFlow = {
    start: {
        question: 'What kind of task are you trying to accomplish?',
        options: [
            { text: 'I need to explore/search a large codebase', next: 'codebaseSize' },
            { text: 'I want users to trigger it with a /command', next: 'skillResult' },
            { text: 'I need to customize how Claude behaves', next: 'contextNeeded' },
            { text: 'I want to run multiple tasks in parallel', next: 'subagentResult' }
        ]
    },
    codebaseSize: {
        question: 'How many files might need to be read?',
        options: [
            { text: 'Just a few files (< 10)', next: 'contextNeeded' },
            { text: 'Many files (10-50)', next: 'subagentResult' },
            { text: 'Lots of files (50+)', next: 'subagentResultStrong' }
        ]
    },
    contextNeeded: {
        question: 'Does the task need access to our conversation history?',
        options: [
            { text: 'Yes, it needs to know what we discussed', next: 'skillResult' },
            { text: 'No, it can work independently', next: 'costSensitive' }
        ]
    },
    costSensitive: {
        question: 'Is cost/token efficiency important for this task?',
        options: [
            { text: 'Yes, I want to minimize token usage', next: 'subagentResult' },
            { text: 'No, quality is more important', next: 'skillResult' }
        ]
    },
    skillResult: {
        result: 'skills',
        title: 'Use a Skill',
        explanation: 'Skills are ideal when you need conversation context, want user-invocable /commands, or need to customize Claude\'s behavior. The instructions load directly into your context for seamless integration.'
    },
    subagentResult: {
        result: 'subagents',
        title: 'Use a Subagent',
        explanation: 'Subagents excel at exploring large codebases, reading many files, or running parallel tasks. They use isolated context and can leverage cheaper models for exploration work.'
    },
    subagentResultStrong: {
        result: 'subagents',
        title: 'Definitely Use a Subagent',
        explanation: 'With 50+ files to explore, a subagent is the clear choice. It keeps your main context clean, can use Haiku for cost efficiency, and returns just the summary you need.'
    }
};

let currentWizardStep = 'start';

// Initialize
function init() {
    updateScenarioContent();
    setupEventListeners();
    renderWizardStep('start');
}

function setupEventListeners() {
    // Scenario buttons
    scenarioButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            scenarioButtons.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            currentScenario = btn.dataset.scenario;
            resetAnimations();
            updateScenarioContent();
        });
    });

    // Play/Reset buttons
    playBtn.addEventListener('click', () => {
        if (!isPlaying) {
            playAnimations();
        }
    });

    resetBtn.addEventListener('click', resetAnimations);

    // Wizard restart
    restartWizard.addEventListener('click', () => {
        wizardResult.style.display = 'none';
        wizardQuestion.style.display = 'block';
        renderWizardStep('start');
    });
}

function updateScenarioContent() {
    const scenario = scenarios[currentScenario];

    // Update skill side
    skillUserMsg.textContent = scenario.userMessage;
    skillInjectContent.textContent = scenario.skillInject;
    skillResponseContent.textContent = scenario.skillResponse;

    // Update subagent side
    subagentUserMsg.textContent = scenario.subagentUserMessage;
    work1.textContent = scenario.agentWork[0];
    work2.textContent = scenario.agentWork[1];
    work3.textContent = scenario.agentWork[2];
    summaryContent.textContent = scenario.summaryContent;
}

function clearTimeouts() {
    animationTimeouts.forEach(t => clearTimeout(t));
    animationTimeouts = [];
}

function resetAnimations() {
    clearTimeouts();
    isPlaying = false;
    playBtn.textContent = 'Play';

    // Reset skill animations
    [skillUser, skillClaude].forEach(el => el.classList.remove('visible'));
    [skillArrow1, skillArrow2, skillArrow3].forEach(el => el.classList.remove('visible'));
    skillUserMsg.classList.remove('visible');
    skillInject.classList.remove('visible');
    skillResponse.classList.remove('visible');

    // Reset subagent animations
    [subagentUser, subagentClaude].forEach(el => el.classList.remove('visible'));
    subagentArrow1.classList.remove('visible');
    subagentUserMsg.classList.remove('visible');
    spawnArrow.classList.remove('visible');
    agentContext.classList.remove('visible');
    [work1, work2, work3].forEach(el => el.classList.remove('visible'));
    returnArrow.classList.remove('visible');
    summaryReturn.classList.remove('visible');
}

function playAnimations() {
    resetAnimations();
    isPlaying = true;
    playBtn.textContent = 'Playing...';

    // Skills Animation Timeline
    const skillTimeline = [
        { delay: 0, action: () => skillUser.classList.add('visible') },
        { delay: 300, action: () => skillUserMsg.classList.add('visible') },
        { delay: 600, action: () => skillArrow1.classList.add('visible') },
        { delay: 900, action: () => skillClaude.classList.add('visible') },
        { delay: 1200, action: () => skillArrow2.classList.add('visible') },
        { delay: 1500, action: () => skillInject.classList.add('visible') },
        { delay: 2000, action: () => skillArrow3.classList.add('visible') },
        { delay: 2300, action: () => skillResponse.classList.add('visible') }
    ];

    // Subagents Animation Timeline
    const subagentTimeline = [
        { delay: 0, action: () => subagentUser.classList.add('visible') },
        { delay: 300, action: () => subagentUserMsg.classList.add('visible') },
        { delay: 600, action: () => subagentArrow1.classList.add('visible') },
        { delay: 900, action: () => subagentClaude.classList.add('visible') },
        { delay: 1200, action: () => spawnArrow.classList.add('visible') },
        { delay: 1500, action: () => agentContext.classList.add('visible') },
        { delay: 1800, action: () => work1.classList.add('visible') },
        { delay: 2100, action: () => work2.classList.add('visible') },
        { delay: 2400, action: () => work3.classList.add('visible') },
        { delay: 2700, action: () => returnArrow.classList.add('visible') },
        { delay: 3000, action: () => summaryReturn.classList.add('visible') }
    ];

    // Execute timelines
    [...skillTimeline, ...subagentTimeline].forEach(({ delay, action }) => {
        const timeout = setTimeout(action, delay);
        animationTimeouts.push(timeout);
    });

    // Reset play button after animations complete
    const finalTimeout = setTimeout(() => {
        isPlaying = false;
        playBtn.textContent = 'Play';
    }, 3500);
    animationTimeouts.push(finalTimeout);
}

// Wizard Functions
function renderWizardStep(stepId) {
    currentWizardStep = stepId;
    const step = wizardFlow[stepId];

    if (step.result) {
        // Show result
        wizardQuestion.style.display = 'none';
        wizardResult.style.display = 'block';

        resultRecommendation.textContent = step.title;
        resultRecommendation.className = 'result-recommendation ' + step.result;
        resultExplanation.textContent = step.explanation;
    } else {
        // Show question
        questionText.textContent = step.question;
        wizardOptions.innerHTML = '';

        step.options.forEach(option => {
            const btn = document.createElement('button');
            btn.className = 'wizard-option';
            btn.textContent = option.text;
            btn.addEventListener('click', () => renderWizardStep(option.next));
            wizardOptions.appendChild(btn);
        });
    }
}

// Start the app
init();

