const resultExplanation = document.getElementById('resultExplanation');
const restartWizard = document.getElementById('restartWizard');

// Wizard Questions
const wizardFlow = {
    start: {
        question: 'What kind of task are you trying to accomplish?',
        options: [
            { text: 'I need to explore/search a large codebase', next: 'codebaseSize' },
            { text: 'I want users to trigger it with a /command', next: 'skillResult' },
            { text: 'I need to customize how Claude behaves', next: 'contextNeeded' },
            { text: 'I want to run multiple tasks in parallel', next: 'subagentResult' }
        ]
    },
    codebaseSize: {
        question: 'How many files might need to be read?',
        options: [
            { text: 'Just a few files (< 10)', next: 'contextNeeded' },
            { text: 'Many files (10-50)', next: 'subagentResult' },
            { text: 'Lots of files (50+)', next: 'subagentResultStrong' }
        ]
    },
    contextNeeded: {
        question: 'Does the task need access to our conversation history?',
        options: [
            { text: 'Yes, it needs to know what we discussed', next: 'skillResult' },
            { text: 'No, it can work independently', next: 'costSensitive' }
        ]
    },
    costSensitive: {
        question: 'Is cost/token efficiency important for this task?',
        options: [
            { text: 'Yes, I want to minimize token usage', next: 'subagentResult' },
            { text: 'No, quality is more important', next: 'skillResult' }
        ]
    },
    skillResult: {
        result: 'skills',
