howMadeBtn.addEventListener('click', () => {
    modalOverlay.classList.add('visible');
    if (!conversationLoaded) {
        loadConversation();
    }
});

modalClose.addEventListener('click', () => {
    modalOverlay.classList.remove('visible');
});

