main {
    max-width: 1400px;
    margin: 0 auto;
    padding: 2rem;
}

/* Scenario Selector */
.scenario-selector {
    text-align: center;
    margin-bottom: 2rem;
}

.scenario-selector h2 {
    margin-bottom: 1rem;
    font-size: 1.5rem;
}

.scenario-buttons {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 1rem;
}

.scenario-btn {
    padding: 0.75rem 1.5rem;
    border: 2px solid var(--border-color);
    border-radius: 8px;
