    // Execute timelines
    [...skillTimeline, ...subagentTimeline].forEach(({ delay, action }) => {
        const timeout = setTimeout(action, delay);
        animationTimeouts.push(timeout);
    });

    // Show recommendation after animations complete
    const recommendTimeout = setTimeout(() => {
