    padding: 3rem 2rem 2rem;
    background: linear-gradient(135deg, var(--claude-purple) 0%, #4c1d95 100%);
    position: relative;
}

/* How Made Button */
.how-made-btn {
    position: absolute;
    top: 1rem;
    right: 1rem;
    padding: 0.5rem 1rem;
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 20px;
    color: white;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s ease;
    backdrop-filter: blur(10px);
}

.how-made-btn:hover {
    background: rgba(255, 255, 255, 0.25);
